def _sum_function(with_fees: bool) -> str:
    fees = " + COALESCE((SELECT SUM(amount) FROM fee_allocation WHERE payment_id = pid), 0)" if with_fees else ""
    return f"""
        CREATE OR REPLACE FUNCTION lt_check_allocation_sum() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE expected bigint; actual bigint; pid uuid := NEW.payment_id;
        BEGIN
          SELECT CASE WHEN p.kind = 'reversal' THEN -p.amount ELSE p.amount END INTO expected
            FROM payment p WHERE p.id = pid;
          SELECT COALESCE(SUM(penalty_part + interest_part + principal_part), 0){fees} INTO actual
            FROM payment_allocation WHERE payment_id = pid;
          IF actual <> expected THEN
            RAISE EXCEPTION 'allocations of payment % sum to %, expected %', pid, actual, expected
              USING ERRCODE = 'check_violation';
          END IF;
          RETURN NULL;
        END $$;
    """


def _schedule_sum(with_replaced: bool) -> str:
    part = ("CASE WHEN replaced THEN paid_principal + waived_principal ELSE principal_part END"
            if with_replaced else "principal_part")
    return f"""
        CREATE OR REPLACE FUNCTION lt_check_schedule_sum() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE expected bigint; actual bigint;
        BEGIN
          SELECT principal INTO expected FROM loan WHERE id = NEW.loan_id;
          SELECT COALESCE(SUM({part}), 0) INTO actual FROM schedule_item WHERE loan_id = NEW.loan_id;
          IF actual <> expected THEN
            RAISE EXCEPTION 'schedule of loan % sums to %, expected %', NEW.loan_id, actual, expected
              USING ERRCODE = 'check_violation';
          END IF;
          RETURN NULL;
        END $$;
    """


def _lock_schedule(with_replaced: bool) -> str:
    extra = " OR (OLD.replaced AND NOT NEW.replaced)" if with_replaced else ""
    return f"""
        CREATE OR REPLACE FUNCTION lt_lock_schedule() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          IF TG_OP = 'DELETE' OR NEW.due_date <> OLD.due_date OR NEW.installment <> OLD.installment
             OR NEW.principal_part <> OLD.principal_part OR NEW.interest_part <> OLD.interest_part
             OR NEW.seq <> OLD.seq OR NEW.loan_id <> OLD.loan_id{extra} THEN
            RAISE EXCEPTION 'schedule rows are locked once the loan is saved'
              USING ERRCODE = 'insufficient_privilege';
          END IF;
          RETURN NEW;
        END $$;
    """


def _upgrade_rules() -> None:
    op.drop_constraint(op.f("ck_loan_adjustment_kind"), "loan_adjustment", type_="check")
    op.create_check_constraint(op.f("ck_loan_adjustment_kind"), "loan_adjustment",
                               "kind in ('settlement_waiver','write_off','penalty_waiver')")
    # A payment may also pay charges: its item and charge allocations together equal its amount,
    # checked whichever table the payment touched.
    op.execute(_sum_function(True))
    op.execute("CREATE CONSTRAINT TRIGGER fee_allocation_sum AFTER INSERT ON fee_allocation "
               "DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION lt_check_allocation_sum()")
    # After a reschedule: principal = what was paid or waived on replaced rows + the current rows.
    op.execute(_schedule_sum(True))
    op.execute("CREATE CONSTRAINT TRIGGER schedule_item_replaced_sum AFTER UPDATE OF replaced ON schedule_item "
               "DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION lt_check_schedule_sum()")
    op.execute(_lock_schedule(True))
    for table in ("fee_allocation", "reschedule"):
        op.execute(f"CREATE TRIGGER {table}_append_only BEFORE UPDATE OR DELETE ON {table} "
                   f"FOR EACH ROW EXECUTE FUNCTION lt_forbid_change()")
        op.execute(f"CREATE TRIGGER {table}_no_truncate BEFORE TRUNCATE ON {table} "
                   f"FOR EACH STATEMENT EXECUTE FUNCTION lt_forbid_change()")
    op.execute("CREATE TRIGGER loan_fee_no_delete BEFORE DELETE ON loan_fee FOR EACH ROW EXECUTE FUNCTION lt_forbid_change()")


def _downgrade_rules() -> None:
    op.execute("DROP TRIGGER IF EXISTS loan_fee_no_delete ON loan_fee")
    for table in ("fee_allocation", "reschedule"):
        op.execute(f"DROP TRIGGER IF EXISTS {table}_append_only ON {table}")
        op.execute(f"DROP TRIGGER IF EXISTS {table}_no_truncate ON {table}")
    op.execute(_lock_schedule(False))
    op.execute("DROP TRIGGER IF EXISTS schedule_item_replaced_sum ON schedule_item")
    op.execute(_schedule_sum(False))
    op.execute("DROP TRIGGER IF EXISTS fee_allocation_sum ON fee_allocation")
    op.execute(_sum_function(False))
    op.drop_constraint(op.f("ck_loan_adjustment_kind"), "loan_adjustment", type_="check")
    op.create_check_constraint(op.f("ck_loan_adjustment_kind"), "loan_adjustment",
                               "kind in ('settlement_waiver','write_off')")
